UPDATE public.mini_apps
SET content_md = $HTML$
<div style="font-family: 'Segoe UI', Arial, sans-serif; max-width: 900px; margin: 0 auto;">

<div style="background: linear-gradient(135deg, #d1fae5 0%, #a7f3d0 50%, #6ee7b7 100%); border-radius: 24px; padding: 45px 30px; text-align: center; margin-bottom: 28px; box-shadow: 0 8px 30px rgba(16,185,129,0.18);">
  <div style="font-size: 68px; margin-bottom: 12px; line-height: 1;">📏</div>
  <h1 style="color: #064e3b; font-size: 30px; margin: 0 0 6px 0;">Escalas Clínicas na Prática</h1>
  <h2 style="color: #047857; font-size: 18px; margin: 0 0 10px 0; font-weight: 500;">8 instrumentos essenciais para transformar observação em decisão segura</h2>
  <div style="width: 60px; height: 3px; background: #064e3b; margin: 12px auto; opacity: 0.35; border-radius: 2px;"></div>
  <p style="color: #065f46; font-size: 14px; margin: 0; font-style: italic;">Braden · Morse · Glasgow · RASS · EVA/Faces · NEWS · PEWS · Fugulin</p>
</div>

<div style="background: #ecfdf5; border-radius: 16px; padding: 22px; margin-bottom: 22px; border-left: 6px solid #10b981;">
  <h3 style="color: #064e3b; margin: 0 0 8px 0; font-size: 17px;">📏 O que é uma escala clínica?</h3>
  <p style="color: #333; line-height: 1.7; font-size: 14px; margin: 0;">É um <strong>instrumento padronizado</strong> que transforma a observação do enfermeiro em uma <strong>pontuação objetiva</strong>. Ajuda a identificar riscos, comparar a evolução do paciente e comunicar achados clínicos com clareza. Escalas <strong>não substituem</strong> a avaliação clínica — elas organizam dados e revelam riscos precocemente.</p>
</div>

<h2 style="color: #064e3b; font-size: 15px; text-transform: uppercase; letter-spacing: 2px; margin: 30px 0 12px 4px;">🛡️ Risco Assistencial</h2>

<details style="background: #f0fdf4; border-radius: 16px; margin-bottom: 12px; border-left: 6px solid #10b981; overflow: hidden;" open>
  <summary style="padding: 18px 22px; cursor: pointer; list-style: none; display: flex; align-items: center; gap: 14px;">
    <div style="width: 44px; height: 44px; background: #10b981; border-radius: 12px; display: grid; place-items: center; font-size: 22px;">🛡️</div>
    <div><div style="font-size: 17px; font-weight: 700; color: #064e3b;">Escala de Braden</div><div style="font-size: 13px; color: #047857;">Risco de Lesão por Pressão (LPP) · toque para abrir</div></div>
  </summary>
  <div style="padding: 0 22px 22px 22px;">
    <div style="background: #fff; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #10b981;"><strong style="color: #064e3b;">🎯 Finalidade:</strong> estimar o risco de LPP a partir de 6 fatores.</div>
    <div style="background: #fefce8; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #eab308;"><strong style="color: #713f12;">📋 Como aplicar:</strong><ol style="margin: 8px 0 0 20px; color: #422006; line-height: 1.7; font-size: 14px;"><li>Avalie cada subitem de 1 a 4 pts (fricção/cisalhamento de 1 a 3).</li><li>Some — total de 6 a 23.</li><li>Quanto <strong>MENOR</strong> o número, <strong>MAIOR</strong> o risco.</li><li>Reavalie a cada 24–48h.</li></ol></div>
    <table style="width: 100%; border-collapse: collapse; background: #fff; border-radius: 12px; overflow: hidden; margin-bottom: 12px; font-size: 13px;">
      <thead><tr style="background: #d1fae5; color: #064e3b;"><th style="padding: 10px; text-align: left;">Subitem</th><th style="padding: 10px;">1</th><th style="padding: 10px;">2</th><th style="padding: 10px;">3</th><th style="padding: 10px;">4</th></tr></thead>
      <tbody style="color: #333;">
        <tr><td style="padding: 8px;"><strong>Percepção sensorial</strong></td><td style="padding: 8px;">Totalmente limitada</td><td style="padding: 8px;">Muito limitada</td><td style="padding: 8px;">Levemente</td><td style="padding: 8px;">Nenhuma</td></tr>
        <tr style="background: #f7fef9;"><td style="padding: 8px;"><strong>Umidade</strong></td><td style="padding: 8px;">Constantemente</td><td style="padding: 8px;">Muito úmida</td><td style="padding: 8px;">Ocasional</td><td style="padding: 8px;">Raramente</td></tr>
        <tr><td style="padding: 8px;"><strong>Atividade</strong></td><td style="padding: 8px;">Acamado</td><td style="padding: 8px;">Cadeira</td><td style="padding: 8px;">Anda às vezes</td><td style="padding: 8px;">Anda frequente</td></tr>
        <tr style="background: #f7fef9;"><td style="padding: 8px;"><strong>Mobilidade</strong></td><td style="padding: 8px;">Imóvel</td><td style="padding: 8px;">Muito limitada</td><td style="padding: 8px;">Levemente</td><td style="padding: 8px;">Sem limitação</td></tr>
        <tr><td style="padding: 8px;"><strong>Nutrição</strong></td><td style="padding: 8px;">Muito pobre</td><td style="padding: 8px;">Inadequada</td><td style="padding: 8px;">Adequada</td><td style="padding: 8px;">Excelente</td></tr>
        <tr style="background: #f7fef9;"><td style="padding: 8px;"><strong>Fricção</strong></td><td style="padding: 8px;">Problema</td><td style="padding: 8px;">Potencial</td><td style="padding: 8px;">Sem problema</td><td style="padding: 8px;">—</td></tr>
      </tbody>
    </table>
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 8px; margin-bottom: 12px;">
      <div style="background: #fee2e2; border-radius: 10px; padding: 10px; border-left: 4px solid #dc2626;"><strong style="color: #7f1d1d; font-size: 13px;">≤9 · Muito alto</strong><div style="font-size: 12px; color: #7f1d1d;">Intervenções máximas.</div></div>
      <div style="background: #fed7aa; border-radius: 10px; padding: 10px; border-left: 4px solid #ea580c;"><strong style="color: #7c2d12; font-size: 13px;">10–12 · Alto</strong><div style="font-size: 12px; color: #7c2d12;">Decúbito rigoroso.</div></div>
      <div style="background: #fef3c7; border-radius: 10px; padding: 10px; border-left: 4px solid #eab308;"><strong style="color: #713f12; font-size: 13px;">13–14 · Moderado</strong><div style="font-size: 12px; color: #713f12;">Reposicionamento.</div></div>
      <div style="background: #d1fae5; border-radius: 10px; padding: 10px; border-left: 4px solid #10b981;"><strong style="color: #064e3b; font-size: 13px;">≥15 · Baixo/sem</strong><div style="font-size: 12px; color: #064e3b;">Cuidados de rotina.</div></div>
    </div>
    <div style="background: #faf5ff; border-radius: 12px; padding: 14px; border-left: 4px solid #a855f7;"><strong style="color: #581c87;">💡 Dica da Enfa:</strong> <span style="color: #3b0764;">Registre pontuação e plano no prontuário. LPP prevenida é qualidade mensurável.</span></div>
  </div>
</details>

<details style="background: #f0fdf4; border-radius: 16px; margin-bottom: 12px; border-left: 6px solid #10b981; overflow: hidden;">
  <summary style="padding: 18px 22px; cursor: pointer; list-style: none; display: flex; align-items: center; gap: 14px;">
    <div style="width: 44px; height: 44px; background: #10b981; border-radius: 12px; display: grid; place-items: center; font-size: 22px;">🚶</div>
    <div><div style="font-size: 17px; font-weight: 700; color: #064e3b;">Escala de Morse</div><div style="font-size: 13px; color: #047857;">Risco de quedas · toque para abrir</div></div>
  </summary>
  <div style="padding: 0 22px 22px 22px;">
    <div style="background: #fff; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #10b981;"><strong style="color: #064e3b;">🎯 Finalidade:</strong> identificar probabilidade de queda e orientar prevenção.</div>
    <div style="background: #fefce8; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #eab308;"><strong style="color: #713f12;">📋 Como aplicar:</strong><ol style="margin: 8px 0 0 20px; color: #422006; line-height: 1.7; font-size: 14px;"><li>Avalie 6 itens — total de 0 a 125.</li><li>Reavalie a cada turno ou após queda.</li><li>Aplique medidas preventivas conforme faixa.</li></ol></div>
    <table style="width: 100%; border-collapse: collapse; background: #fff; border-radius: 12px; overflow: hidden; margin-bottom: 12px; font-size: 13px;">
      <thead><tr style="background: #d1fae5; color: #064e3b;"><th style="padding: 10px; text-align: left;">Item</th><th style="padding: 10px; text-align: left;">Opções</th><th style="padding: 10px;">Pts</th></tr></thead>
      <tbody style="color: #333;">
        <tr><td style="padding: 8px;">Histórico de quedas</td><td style="padding: 8px;">Não / Sim</td><td style="padding: 8px;">0 / 25</td></tr>
        <tr style="background: #f7fef9;"><td style="padding: 8px;">Dx secundário</td><td style="padding: 8px;">Não / Sim</td><td style="padding: 8px;">0 / 15</td></tr>
        <tr><td style="padding: 8px;">Auxílio</td><td style="padding: 8px;">Nenhum / Muletas / Móveis</td><td style="padding: 8px;">0 / 15 / 30</td></tr>
        <tr style="background: #f7fef9;"><td style="padding: 8px;">EV / heparina</td><td style="padding: 8px;">Não / Sim</td><td style="padding: 8px;">0 / 20</td></tr>
        <tr><td style="padding: 8px;">Marcha</td><td style="padding: 8px;">Normal / Fraca / Cambaleante</td><td style="padding: 8px;">0 / 10 / 20</td></tr>
        <tr style="background: #f7fef9;"><td style="padding: 8px;">Estado mental</td><td style="padding: 8px;">Orientado / Superestima</td><td style="padding: 8px;">0 / 15</td></tr>
      </tbody>
    </table>
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 8px; margin-bottom: 12px;">
      <div style="background: #d1fae5; border-radius: 10px; padding: 10px; border-left: 4px solid #10b981;"><strong style="color: #064e3b; font-size: 13px;">0–24 · Baixo</strong><div style="font-size: 12px; color: #064e3b;">Cuidados básicos.</div></div>
      <div style="background: #fef3c7; border-radius: 10px; padding: 10px; border-left: 4px solid #eab308;"><strong style="color: #713f12; font-size: 13px;">25–44 · Moderado</strong><div style="font-size: 12px; color: #713f12;">Protocolo padrão.</div></div>
      <div style="background: #fee2e2; border-radius: 10px; padding: 10px; border-left: 4px solid #dc2626;"><strong style="color: #7f1d1d; font-size: 13px;">≥45 · Alto</strong><div style="font-size: 12px; color: #7f1d1d;">Grades, supervisão.</div></div>
    </div>
    <div style="background: #faf5ff; border-radius: 12px; padding: 14px; border-left: 4px solid #a855f7;"><strong style="color: #581c87;">💡 Dica da Enfa:</strong> <span style="color: #3b0764;">Pulseira + orientar família. Prevenção compartilhada.</span></div>
  </div>
</details>

<h2 style="color: #1e3a8a; font-size: 15px; text-transform: uppercase; letter-spacing: 2px; margin: 30px 0 12px 4px;">🧠 Neurológicas</h2>

<details style="background: #eff6ff; border-radius: 16px; margin-bottom: 12px; border-left: 6px solid #3b82f6; overflow: hidden;">
  <summary style="padding: 18px 22px; cursor: pointer; list-style: none; display: flex; align-items: center; gap: 14px;">
    <div style="width: 44px; height: 44px; background: #3b82f6; border-radius: 12px; display: grid; place-items: center; font-size: 22px;">🧠</div>
    <div><div style="font-size: 17px; font-weight: 700; color: #1e3a8a;">Glasgow (ECG)</div><div style="font-size: 13px; color: #1d4ed8;">Nível de consciência · toque para abrir</div></div>
  </summary>
  <div style="padding: 0 22px 22px 22px;">
    <div style="background: #fff; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #3b82f6;"><strong style="color: #1e3a8a;">🎯 Finalidade:</strong> avaliar consciência por 3 parâmetros: ocular, verbal e motora.</div>
    <div style="background: #fefce8; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #eab308;"><strong style="color: #713f12;">📋 Como aplicar:</strong><ol style="margin: 8px 0 0 20px; color: #422006; line-height: 1.7; font-size: 14px;"><li>Observe a <strong>MELHOR</strong> resposta em cada parâmetro.</li><li>Some — total de 3 (coma) a 15 (alerta).</li><li>Registre <strong>O__V__M__</strong> (ex: O3V4M5=12).</li><li>ECG-P: avalie pupilas (subtrai 0/1/2).</li></ol></div>
    <table style="width: 100%; border-collapse: collapse; background: #fff; border-radius: 12px; overflow: hidden; margin-bottom: 12px; font-size: 13px;">
      <thead><tr style="background: #dbeafe; color: #1e3a8a;"><th style="padding: 10px;">Pts</th><th style="padding: 10px; text-align: left;">Ocular</th><th style="padding: 10px; text-align: left;">Verbal</th><th style="padding: 10px; text-align: left;">Motora</th></tr></thead>
      <tbody style="color: #333;">
        <tr><td style="padding: 8px; text-align: center; font-weight: 700;">6</td><td style="padding: 8px;">—</td><td style="padding: 8px;">—</td><td style="padding: 8px;">Obedece</td></tr>
        <tr style="background: #f5faff;"><td style="padding: 8px; text-align: center; font-weight: 700;">5</td><td style="padding: 8px;">—</td><td style="padding: 8px;">Orientada</td><td style="padding: 8px;">Localiza dor</td></tr>
        <tr><td style="padding: 8px; text-align: center; font-weight: 700;">4</td><td style="padding: 8px;">Espontânea</td><td style="padding: 8px;">Confusa</td><td style="padding: 8px;">Flexão normal</td></tr>
        <tr style="background: #f5faff;"><td style="padding: 8px; text-align: center; font-weight: 700;">3</td><td style="padding: 8px;">Ao som</td><td style="padding: 8px;">Inapropriadas</td><td style="padding: 8px;">Decorticação</td></tr>
        <tr><td style="padding: 8px; text-align: center; font-weight: 700;">2</td><td style="padding: 8px;">À pressão</td><td style="padding: 8px;">Incompreensíveis</td><td style="padding: 8px;">Descerebração</td></tr>
        <tr style="background: #f5faff;"><td style="padding: 8px; text-align: center; font-weight: 700;">1</td><td style="padding: 8px;">Ausente</td><td style="padding: 8px;">Ausente</td><td style="padding: 8px;">Ausente</td></tr>
      </tbody>
    </table>
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 8px; margin-bottom: 12px;">
      <div style="background: #d1fae5; border-radius: 10px; padding: 10px; border-left: 4px solid #10b981;"><strong style="color: #064e3b; font-size: 13px;">13–15 · Leve</strong></div>
      <div style="background: #fef3c7; border-radius: 10px; padding: 10px; border-left: 4px solid #eab308;"><strong style="color: #713f12; font-size: 13px;">9–12 · Moderado</strong></div>
      <div style="background: #fee2e2; border-radius: 10px; padding: 10px; border-left: 4px solid #dc2626;"><strong style="color: #7f1d1d; font-size: 13px;">3–8 · Grave (coma)</strong></div>
    </div>
    <div style="background: #faf5ff; border-radius: 12px; padding: 14px; border-left: 4px solid #a855f7;"><strong style="color: #581c87;">💡 Dica da Enfa:</strong> <span style="color: #3b0764;">Nunca registre "Glasgow 3" sem O V M — a decomposição guia a conduta.</span></div>
  </div>
</details>

<details style="background: #eff6ff; border-radius: 16px; margin-bottom: 12px; border-left: 6px solid #3b82f6; overflow: hidden;">
  <summary style="padding: 18px 22px; cursor: pointer; list-style: none; display: flex; align-items: center; gap: 14px;">
    <div style="width: 44px; height: 44px; background: #3b82f6; border-radius: 12px; display: grid; place-items: center; font-size: 22px;">💤</div>
    <div><div style="font-size: 17px; font-weight: 700; color: #1e3a8a;">RASS</div><div style="font-size: 13px; color: #1d4ed8;">Sedação/agitação em UTI · toque para abrir</div></div>
  </summary>
  <div style="padding: 0 22px 22px 22px;">
    <div style="background: #fff; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #3b82f6;"><strong style="color: #1e3a8a;">🎯 Finalidade:</strong> avaliar sedação/agitação no crítico (VM) para ajustar sedativos.</div>
    <div style="background: #fefce8; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #eab308;"><strong style="color: #713f12;">📋 Como aplicar:</strong><ol style="margin: 8px 0 0 20px; color: #422006; line-height: 1.7; font-size: 14px;"><li>Observe 10s sem tocar.</li><li>Chame pelo nome.</li><li>Estímulo físico se não responder.</li><li>Classifique +4 a −5.</li></ol></div>
    <table style="width: 100%; border-collapse: collapse; background: #fff; border-radius: 12px; overflow: hidden; margin-bottom: 12px; font-size: 13px;">
      <thead><tr style="background: #dbeafe; color: #1e3a8a;"><th style="padding: 8px;">Pts</th><th style="padding: 8px; text-align: left;">Termo</th><th style="padding: 8px; text-align: left;">Descrição</th></tr></thead>
      <tbody style="color: #333;">
        <tr><td style="padding: 8px; text-align: center; font-weight: 700; color: #dc2626;">+4</td><td style="padding: 8px;">Combativo</td><td style="padding: 8px;">Violento, perigo.</td></tr>
        <tr style="background: #f5faff;"><td style="padding: 8px; text-align: center; font-weight: 700; color: #dc2626;">+3</td><td style="padding: 8px;">Muito agitado</td><td style="padding: 8px;">Puxa tubos.</td></tr>
        <tr><td style="padding: 8px; text-align: center; font-weight: 700; color: #ea580c;">+2</td><td style="padding: 8px;">Agitado</td><td style="padding: 8px;">Briga ventilador.</td></tr>
        <tr style="background: #f5faff;"><td style="padding: 8px; text-align: center; font-weight: 700; color: #eab308;">+1</td><td style="padding: 8px;">Inquieto</td><td style="padding: 8px;">Ansioso.</td></tr>
        <tr><td style="padding: 8px; text-align: center; font-weight: 700; color: #10b981;">0</td><td style="padding: 8px;"><strong>Alerta e calmo</strong></td><td style="padding: 8px;">Alvo ideal.</td></tr>
        <tr style="background: #f5faff;"><td style="padding: 8px; text-align: center; font-weight: 700; color: #3b82f6;">−1</td><td style="padding: 8px;">Sonolento</td><td style="padding: 8px;">Desperta &gt;10s.</td></tr>
        <tr><td style="padding: 8px; text-align: center; font-weight: 700; color: #3b82f6;">−2</td><td style="padding: 8px;">Sedação leve</td><td style="padding: 8px;">Desperta &lt;10s.</td></tr>
        <tr style="background: #f5faff;"><td style="padding: 8px; text-align: center; font-weight: 700; color: #6366f1;">−3</td><td style="padding: 8px;">Moderada</td><td style="padding: 8px;">Sem contato visual.</td></tr>
        <tr><td style="padding: 8px; text-align: center; font-weight: 700; color: #7c3aed;">−4</td><td style="padding: 8px;">Profunda</td><td style="padding: 8px;">Só estímulo físico.</td></tr>
        <tr style="background: #f5faff;"><td style="padding: 8px; text-align: center; font-weight: 700; color: #6b21a8;">−5</td><td style="padding: 8px;">Não desperta</td><td style="padding: 8px;">Sem resposta.</td></tr>
      </tbody>
    </table>
    <div style="background: #faf5ff; border-radius: 12px; padding: 14px; border-left: 4px solid #a855f7;"><strong style="color: #581c87;">💡 Dica da Enfa:</strong> <span style="color: #3b0764;">Alvo geral <strong>0 a −2</strong>. Reavalie 4/4h. Reduz tempo de VM.</span></div>
  </div>
</details>

<h2 style="color: #9f1239; font-size: 15px; text-transform: uppercase; letter-spacing: 2px; margin: 30px 0 12px 4px;">😣 Dor</h2>

<details style="background: #fff1f2; border-radius: 16px; margin-bottom: 12px; border-left: 6px solid #f43f5e; overflow: hidden;">
  <summary style="padding: 18px 22px; cursor: pointer; list-style: none; display: flex; align-items: center; gap: 14px;">
    <div style="width: 44px; height: 44px; background: #f43f5e; border-radius: 12px; display: grid; place-items: center; font-size: 22px;">😣</div>
    <div><div style="font-size: 17px; font-weight: 700; color: #9f1239;">EVA e Escala de Faces</div><div style="font-size: 13px; color: #be123c;">Intensidade da dor · toque para abrir</div></div>
  </summary>
  <div style="padding: 0 22px 22px 22px;">
    <div style="background: #fff; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #f43f5e;"><strong style="color: #9f1239;">🎯 Finalidade:</strong> quantificar a dor para orientar analgesia e avaliar eficácia.</div>
    <div style="background: #fefce8; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #eab308;"><strong style="color: #713f12;">📋 Como aplicar:</strong><ol style="margin: 8px 0 0 20px; color: #422006; line-height: 1.7; font-size: 14px;"><li><strong>EVA</strong>: 0 (sem) a 10 (pior imaginável).</li><li><strong>Faces</strong>: crianças ≥3a, idosos, dificuldade verbal.</li><li>Registre valor, local e características.</li><li>Reavalie 30 min (EV) / 60 min (VO) após.</li></ol></div>
    <table style="width: 100%; border-collapse: collapse; background: #fff; border-radius: 12px; overflow: hidden; margin-bottom: 12px; font-size: 13px;">
      <thead><tr style="background: #ffe4e6; color: #9f1239;"><th style="padding: 8px;">Score</th><th style="padding: 8px; text-align: left;">EVA</th><th style="padding: 8px;">Face</th><th style="padding: 8px; text-align: left;">Ação</th></tr></thead>
      <tbody style="color: #333;">
        <tr><td style="padding: 8px; text-align: center; font-weight: 700;">0</td><td style="padding: 8px;">Sem dor</td><td style="padding: 8px; text-align: center; font-size: 20px;">😀</td><td style="padding: 8px;">Nenhuma intervenção.</td></tr>
        <tr style="background: #fef7f7;"><td style="padding: 8px; text-align: center; font-weight: 700;">1–3</td><td style="padding: 8px;">Leve</td><td style="padding: 8px; text-align: center; font-size: 20px;">🙂</td><td style="padding: 8px;">Não farm. + simples.</td></tr>
        <tr><td style="padding: 8px; text-align: center; font-weight: 700;">4–6</td><td style="padding: 8px;">Moderada</td><td style="padding: 8px; text-align: center; font-size: 20px;">😐</td><td style="padding: 8px;">Programada, opioide fraco.</td></tr>
        <tr style="background: #fef7f7;"><td style="padding: 8px; text-align: center; font-weight: 700;">7–9</td><td style="padding: 8px;">Intensa</td><td style="padding: 8px; text-align: center; font-size: 20px;">😣</td><td style="padding: 8px;">Potente, comunicar médico.</td></tr>
        <tr><td style="padding: 8px; text-align: center; font-weight: 700;">10</td><td style="padding: 8px;">Insuportável</td><td style="padding: 8px; text-align: center; font-size: 20px;">😭</td><td style="padding: 8px;"><strong>Emergência</strong>.</td></tr>
      </tbody>
    </table>
    <div style="background: #faf5ff; border-radius: 12px; padding: 14px; border-left: 4px solid #a855f7;"><strong style="color: #581c87;">💡 Dica da Enfa:</strong> <span style="color: #3b0764;">Dor é o <strong>5º sinal vital</strong>. Dor é o que o paciente diz que é.</span></div>
  </div>
</details>

<h2 style="color: #7c2d12; font-size: 15px; text-transform: uppercase; letter-spacing: 2px; margin: 30px 0 12px 4px;">❤️ Deterioração Clínica</h2>

<details style="background: #fff7ed; border-radius: 16px; margin-bottom: 12px; border-left: 6px solid #f97316; overflow: hidden;">
  <summary style="padding: 18px 22px; cursor: pointer; list-style: none; display: flex; align-items: center; gap: 14px;">
    <div style="width: 44px; height: 44px; background: #f97316; border-radius: 12px; display: grid; place-items: center; font-size: 22px;">❤️</div>
    <div><div style="font-size: 17px; font-weight: 700; color: #7c2d12;">NEWS</div><div style="font-size: 13px; color: #9a3412;">Alerta precoce adulto · toque para abrir</div></div>
  </summary>
  <div style="padding: 0 22px 22px 22px;">
    <div style="background: #fff; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #f97316;"><strong style="color: #7c2d12;">🎯 Finalidade:</strong> identificar precocemente adultos com risco de deterioração.</div>
    <div style="background: #fefce8; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #eab308;"><strong style="color: #713f12;">📋 Como aplicar:</strong><ol style="margin: 8px 0 0 20px; color: #422006; line-height: 1.7; font-size: 14px;"><li>Verifique os 7 parâmetros.</li><li>0 a 3 pts cada — total 0 a 20.</li><li>Aplique reavaliação conforme faixa.</li></ol></div>
    <table style="width: 100%; border-collapse: collapse; background: #fff; border-radius: 12px; overflow: hidden; margin-bottom: 12px; font-size: 12px;">
      <thead><tr style="background: #ffedd5; color: #7c2d12;"><th style="padding: 8px; text-align: left;">Parâmetro</th><th style="padding: 8px;">3</th><th style="padding: 8px;">2</th><th style="padding: 8px;">1</th><th style="padding: 8px;">0</th><th style="padding: 8px;">1</th><th style="padding: 8px;">2</th><th style="padding: 8px;">3</th></tr></thead>
      <tbody style="color: #333;">
        <tr><td style="padding: 6px;"><strong>FR</strong></td><td style="padding: 6px; text-align: center;">≤8</td><td style="padding: 6px; text-align: center;">—</td><td style="padding: 6px; text-align: center;">9–11</td><td style="padding: 6px; text-align: center;">12–20</td><td style="padding: 6px; text-align: center;">—</td><td style="padding: 6px; text-align: center;">21–24</td><td style="padding: 6px; text-align: center;">≥25</td></tr>
        <tr style="background: #fffaf3;"><td style="padding: 6px;"><strong>SpO₂</strong></td><td style="padding: 6px; text-align: center;">≤91</td><td style="padding: 6px; text-align: center;">92–93</td><td style="padding: 6px; text-align: center;">94–95</td><td style="padding: 6px; text-align: center;">≥96</td><td style="padding: 6px; text-align: center;">—</td><td style="padding: 6px; text-align: center;">—</td><td style="padding: 6px; text-align: center;">—</td></tr>
        <tr><td style="padding: 6px;"><strong>Temp</strong></td><td style="padding: 6px; text-align: center;">≤35</td><td style="padding: 6px; text-align: center;">—</td><td style="padding: 6px; text-align: center;">35–36</td><td style="padding: 6px; text-align: center;">36–38</td><td style="padding: 6px; text-align: center;">38–39</td><td style="padding: 6px; text-align: center;">≥39</td><td style="padding: 6px; text-align: center;">—</td></tr>
        <tr style="background: #fffaf3;"><td style="padding: 6px;"><strong>PAS</strong></td><td style="padding: 6px; text-align: center;">≤90</td><td style="padding: 6px; text-align: center;">91–100</td><td style="padding: 6px; text-align: center;">101–110</td><td style="padding: 6px; text-align: center;">111–219</td><td style="padding: 6px; text-align: center;">—</td><td style="padding: 6px; text-align: center;">—</td><td style="padding: 6px; text-align: center;">≥220</td></tr>
        <tr><td style="padding: 6px;"><strong>FC</strong></td><td style="padding: 6px; text-align: center;">≤40</td><td style="padding: 6px; text-align: center;">—</td><td style="padding: 6px; text-align: center;">41–50</td><td style="padding: 6px; text-align: center;">51–90</td><td style="padding: 6px; text-align: center;">91–110</td><td style="padding: 6px; text-align: center;">111–130</td><td style="padding: 6px; text-align: center;">≥131</td></tr>
      </tbody>
    </table>
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 8px; margin-bottom: 12px;">
      <div style="background: #d1fae5; border-radius: 10px; padding: 10px; border-left: 4px solid #10b981;"><strong style="color: #064e3b; font-size: 13px;">0 · Baixo</strong><div style="font-size: 12px; color: #064e3b;">Reavaliar 12h.</div></div>
      <div style="background: #fef3c7; border-radius: 10px; padding: 10px; border-left: 4px solid #eab308;"><strong style="color: #713f12; font-size: 13px;">1–4 · Baixo/médio</strong><div style="font-size: 12px; color: #713f12;">4–6h.</div></div>
      <div style="background: #fed7aa; border-radius: 10px; padding: 10px; border-left: 4px solid #ea580c;"><strong style="color: #7c2d12; font-size: 13px;">5–6 · Médio</strong><div style="font-size: 12px; color: #7c2d12;">Horária.</div></div>
      <div style="background: #fee2e2; border-radius: 10px; padding: 10px; border-left: 4px solid #dc2626;"><strong style="color: #7f1d1d; font-size: 13px;">≥7 · Alto</strong><div style="font-size: 12px; color: #7f1d1d;">Contínua, UTI.</div></div>
    </div>
    <div style="background: #faf5ff; border-radius: 12px; padding: 14px; border-left: 4px solid #a855f7;"><strong style="color: #581c87;">💡 Dica da Enfa:</strong> <span style="color: #3b0764;">Se algo parece errado, comunique mesmo com escore baixo.</span></div>
  </div>
</details>

<details style="background: #fff7ed; border-radius: 16px; margin-bottom: 12px; border-left: 6px solid #f97316; overflow: hidden;">
  <summary style="padding: 18px 22px; cursor: pointer; list-style: none; display: flex; align-items: center; gap: 14px;">
    <div style="width: 44px; height: 44px; background: #f97316; border-radius: 12px; display: grid; place-items: center; font-size: 22px;">👶</div>
    <div><div style="font-size: 17px; font-weight: 700; color: #7c2d12;">PEWS</div><div style="font-size: 13px; color: #9a3412;">Alerta precoce pediátrico · toque para abrir</div></div>
  </summary>
  <div style="padding: 0 22px 22px 22px;">
    <div style="background: #fff; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #f97316;"><strong style="color: #7c2d12;">🎯 Finalidade:</strong> detectar precocemente deterioração pediátrica.</div>
    <div style="background: #fefce8; border-radius: 12px; padding: 14px; margin-bottom: 12px; border-left: 4px solid #eab308;"><strong style="color: #713f12;">📋 Como aplicar:</strong><ol style="margin: 8px 0 0 20px; color: #422006; line-height: 1.7; font-size: 14px;"><li>3 domínios: comportamento, CV, respiratório.</li><li>0 a 3 pts cada — total 0 a 9.</li><li>+2 pts se nebulização contínua/vômitos pós-op.</li></ol></div>
    <table style="width: 100%; border-collapse: collapse; background: #fff; border-radius: 12px; overflow: hidden; margin-bottom: 12px; font-size: 13px;">
      <thead><tr style="background: #ffedd5; color: #7c2d12;"><th style="padding: 8px; text-align: left;">Domínio</th><th style="padding: 8px;">0</th><th style="padding: 8px;">1</th><th style="padding: 8px;">2</th><th style="padding: 8px;">3</th></tr></thead>
      <tbody style="color: #333;">
        <tr><td style="padding: 8px;"><strong>Comportamento</strong></td><td style="padding: 8px;">Brincando</td><td style="padding: 8px;">Sonolento</td><td style="padding: 8px;">Irritado</td><td style="padding: 8px;">Letárgico</td></tr>
        <tr style="background: #fffaf3;"><td style="padding: 8px;"><strong>Cardiovascular</strong></td><td style="padding: 8px;">Rosado EC 1–2s</td><td style="padding: 8px;">Pálido EC 3s</td><td style="padding: 8px;">Cianótico</td><td style="padding: 8px;">Cinzento EC ≥5s</td></tr>
        <tr><td style="padding: 8px;"><strong>Respiratório</strong></td><td style="padding: 8px;">Normal</td><td style="padding: 8px;">FR↑10</td><td style="padding: 8px;">FR↑20 retrações</td><td style="padding: 8px;">FR↓5 gemência</td></tr>
      </tbody>
    </table>
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 8px; margin-bottom: 12px;">
      <div style="background: #d1fae5; border-radius: 10px; padding: 10px; border-left: 4px solid #10b981;"><strong style="color: #064e3b; font-size: 12px;">0–2 · Rotina</strong></div>
      <div style="background: #fef3c7; border-radius: 10px; padding: 10px; border-left: 4px solid #eab308;"><strong style="color: #713f12; font-size: 12px;">3 · Reavaliar 1h</strong></div>
      <div style="background: #fed7aa; border-radius: 10px; padding: 10px; border-left: 4px solid #ea580c;"><strong style="color: #7c2d12; font-size: 12px;">4 · Médico</strong></div>
      <div style="background: #fee2e2; border-radius: 10px; padding: 10px; border-left: 4px solid #dc2626;"><strong style="color: #7f1d1d; font-size: 12px;">≥5 · Time rápido</strong></div>
    </div>
    <div style="background: #faf5ff; border-radius: 12px; padding: 14px; border-left: 4px solid #a855f7;"><strong style="color: #581c87;">💡 Dica da Enfa:</strong> <span style="color: #3b0764;">Mudanças de comportamento aparecem antes dos sinais vitais. Confie no que a mãe/pai relata.</span></div>
  </div>
</details>

<h2 style="color: #581c87; font-size: 15px; text-transform: uppercase; letter-spacing: 2px; margin: 30px 0 12px 4px;">👥 Gerencial</h2>

<details style="background: #faf5ff; border-radius: 16px; margin-bottom: 12px; border-left: 6px solid #a855f7; overflow: hidden;">
  <summary style="padding: 18px 22px; cursor: pointer; list-style: none; display: flex; align-items: center; gap: 14px;">
    <div style="width: 44px; height: 44px; background: #a855f7; border-radius: 12px; display: grid; place-items: center; font-size: 22px;">👥</div>
    <div><div style="font-size: 17px; font-weight: 700; color: #581c87;">Fugulin</div><div style="font-size: 13px; color: #6b21a8;">Dependência e dimensionamento · toque para abrir</div></div>
  </summary>
  <div style="padding: 0 22px 22px 22px;">
