      <tbody style="color: #333;">
        <tr><td style="padding: 8px;"><strong>Estado mental</strong></td><td style="padding: 8px;">Orientado</td><td style="padding: 8px;">Desor. períodos</td><td style="padding: 8px;">Desor. constante</td><td style="padding: 8px;">Inconsciente</td></tr>
        <tr style="background: #fdfaff;"><td style="padding: 8px;"><strong>Oxigenação</strong></td><td style="padding: 8px;">Sem O₂</td><td style="padding: 8px;">Intermitente</td><td style="padding: 8px;">Contínuo</td><td style="padding: 8px;">VM</td></tr>
        <tr><td style="padding: 8px;"><strong>SSVV</strong></td><td style="padding: 8px;">4x/dia</td><td style="padding: 8px;">6x/dia</td><td style="padding: 8px;">2/2h</td><td style="padding: 8px;">≤1/1h</td></tr>
        <tr style="background: #fdfaff;"><td style="padding: 8px;"><strong>Motilidade</strong></td><td style="padding: 8px;">Todos</td><td style="padding: 8px;">Limitação</td><td style="padding: 8px;">Grave</td><td style="padding: 8px;">Incapaz</td></tr>
        <tr><td style="padding: 8px;"><strong>Deambulação</strong></td><td style="padding: 8px;">Ambulante</td><td style="padding: 8px;">Auxílio</td><td style="padding: 8px;">Leito senta</td><td style="padding: 8px;">Leito decúbito</td></tr>
        <tr style="background: #fdfaff;"><td style="padding: 8px;"><strong>Alimentação</strong></td><td style="padding: 8px;">VO</td><td style="padding: 8px;">VO auxílio</td><td style="padding: 8px;">SNE/SNG</td><td style="padding: 8px;">NPT</td></tr>
        <tr><td style="padding: 8px;"><strong>Cuidado corporal</strong></td><td style="padding: 8px;">Autocuidado</td><td style="padding: 8px;">Auxílio</td><td style="padding: 8px;">Dependente</td><td style="padding: 8px;">+ curativos</td></tr>
        <tr style="background: #fdfaff;"><td style="padding: 8px;"><strong>Eliminações</strong></td><td style="padding: 8px;">Autocuidado</td><td style="padding: 8px;">Comadre c/ ajuda</td><td style="padding: 8px;">Fralda</td><td style="padding: 8px;">Assistida</td></tr>
        <tr><td style="padding: 8px;"><strong>Terapêutica</strong></td><td style="padding: 8px;">VO/IM</td><td style="padding: 8px;">EV interm.</td><td style="padding: 8px;">EV contínua</td><td style="padding: 8px;">Vasoativas</td></tr>
      </tbody>
    </table>
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 8px; margin-bottom: 12px;">
